const fs=require('fs'),path=require('path'),crypto=require('crypto');
(async()=>{
const prettier=require('prettier'),b='docs/planning/prototype-v3/',root='docs/quality-gate/reports/local-use-baseline-20260913/';
const docs=['AGENTS.md',b+'19-开发路线图-20260912.md',b+'20-Codex交接提示词-20260912.md',b+'42-本机启用方案与范围确认-20260914.md',b+'README.md','output/pfc-workbench-prototype/README.md'];
const sha=f=>crypto.createHash('sha256').update(fs.readFileSync(f)).digest('hex'),errors=[];let links=0;
for(const f of docs){const s=fs.readFileSync(f,'utf8');if(!await prettier.check(s,{...await prettier.resolveConfig(f),filepath:f}))errors.push('format '+f);
for(const m of s.matchAll(/\]\(([^)]+)\)/g)){let ref=m[1];if(/^(https?:|#|\{)/.test(ref))continue;ref=decodeURIComponent(ref.split('#')[0]);if(!fs.existsSync(path.resolve(path.dirname(f),ref)))errors.push('link '+f+' '+ref);links++;}}
const g=JSON.parse(fs.readFileSync(root+'gates-1789317348153.json')),p=JSON.parse(fs.readFileSync(root+'protected-baseline.json')),a=JSON.parse(fs.readFileSync(root+'acceptance-20260914.json'));let protectedCount=0;
for(const[f,h]of Object.entries(g.sourceHashes))if(sha(f)!==h)errors.push('source '+f);
for(const[f,h]of Object.entries(p.hashes))if(!(f in g.sourceHashes)){protectedCount++;if(sha(f)!==h)errors.push('protected '+f);}
for(const[f,h]of Object.entries(a.immutableEvidence))if(sha(root+f)!==h)errors.push('evidence '+f);
if(sha(root+a.gateEvidence.file)!==a.gateEvidence.sha256||g.status!=='PASS'||g.gates.length!==35||!g.gates.every(x=>x.exitCode===0&&x.status==='PASS'))errors.push('gate provenance');
const pkg=JSON.parse(fs.readFileSync('docs/quality-gate/reports/local-activation-20260914/operation-package.json'));
if(pkg.status!=='PENDING_USER_CONFIRMATION'||pkg.primaryTarget.schema!=='pfc_workbench'||pkg.executionDocuments.length!==7)errors.push('package scope');
const registry=require('./server/src/persistence/migrations').registry('006');
if(pkg.initialization.existingMigrations.some((m,i)=>m.checksum!==registry[i].checksum))errors.push('migration checksum');
const scriptCount=[...fs.readFileSync('output/pfc-workbench-prototype/index.html','utf8').matchAll(/<script\b[^>]*\bsrc=/g)].length;
if(scriptCount!==43)errors.push('script count');
const result={at:new Date().toISOString(),status:errors.length?'FAIL':'PASS',documents:docs.length,links,sourceHashes:68,protectedCount,immutableEvidenceHashes:9,historicalGates:35,historicalGatesRerun:false,indexScripts:scriptCount,executionAuthorization:pkg.status,errors};
console.log(JSON.stringify(result));if(errors.length)process.exitCode=1;
})().catch(e=>{console.error(e.message);process.exitCode=1});
